CREATE TABLE IF NOT EXISTS offer_prices (offer_id TEXT NOT NULL,observed_on TEXT NOT NULL,price REAL NOT NULL,observed_at INTEGER NOT NULL,PRIMARY KEY (offer_id,observed_on));
CREATE INDEX IF NOT EXISTS idx_offer_prices_offer_time ON offer_prices(offer_id,observed_at DESC);
CREATE TABLE IF NOT EXISTS offer_feedback (offer_id TEXT NOT NULL,kind TEXT NOT NULL,quantity INTEGER NOT NULL DEFAULT 0,updated_at INTEGER NOT NULL,PRIMARY KEY (offer_id,kind));
UPDATE offers SET category=CASE WHEN lower(category) LIKE '%infantil%' OR lower(category) LIKE '%bebe%' OR lower(category) LIKE '%crianca%' OR lower(category) LIKE '%brinquedo%' THEN 'infantil' WHEN lower(category) LIKE '%livr%' THEN 'livros' WHEN lower(category) LIKE '%pet%' THEN 'pet' WHEN lower(category) LIKE '%cozinha%' THEN 'cozinha' WHEN lower(category) LIKE '%ferrament%' OR lower(category) LIKE '%industrial%' THEN 'ferramentas' WHEN lower(category) LIKE '%automot%' OR lower(category) LIKE '%carro%' THEN 'automotivo' WHEN lower(category) LIKE '%esport%' OR lower(category) LIKE '%fitness%' THEN 'esportes' WHEN lower(category) LIKE '%sapato%' OR lower(category) LIKE '%moda%' OR lower(category) LIKE '%roupa%' THEN 'moda' WHEN lower(category) LIKE '%eletron%' OR lower(category) LIKE '%tecnolog%' THEN 'eletronicos' WHEN lower(category) LIKE '%beleza%' OR lower(category) LIKE '%saude%' THEN 'beleza' WHEN lower(category) LIKE '%casa%' OR lower(category) LIKE '%decor%' THEN 'casa' ELSE 'outros' END;
INSERT OR IGNORE INTO offer_prices(offer_id,observed_on,price,observed_at) SELECT id,date(published_at,'unixepoch'),price,published_at FROM offers;
PRAGMA optimize;
